edits.with:
.cs.flux{background:linear-gradient(90deg,var(--psy3),var(--psy1))} .cs.ill{background:var(--psy1);box-shadow:inset 0 0 0 1.5px var(--psy3)} .brief .cs.sub{margin:0}
/* ============ Mimic course tables v6 (s111, Jonathan): a key inside every row, hub groups as panels, rows as cards ============ */
.lcc{--card:#FCFCFC}
.lcc .wrows{display:flex;flex-direction:column;gap:10px}
.lcc .wgb{padding:10px 8px 8px;border-radius:14px;background:color-mix(in srgb,var(--recess) 70%,transparent)}
.lcc .wgb + .wgb{margin-top:8px}
.lcc .wgb > .wg{margin:2px 6px 9px;padding:0;border:0;font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--chart-ink);opacity:.75}
.lcc .cr,.lcc .wg + .cr{padding:13px 14px 12px;border:1px solid var(--hair);border-radius:12px;background:var(--card);box-shadow:0 1px 2px rgba(24,28,30,.05)}
.lcc .rk{display:flex;flex-wrap:wrap;gap:4px 12px;margin:3px 0 9px;font-size:11.5px;line-height:1.35;color:var(--muted)}
.lcc .rk span{display:inline-flex;align-items:center;gap:5px}
.lcc .rk i.cs{position:static;display:inline-block;flex:none;width:14px;height:9px;margin:0;border-radius:3px}
.lcc .rk i.cs.mark{width:5px;height:12px;border-radius:2px}
.lcc .wl{margin:0 0 2px;font-size:13.5px;line-height:1.45}
.lcc .rax span{opacity:.8}
@media (max-width:560px){.lcc .wgb{padding:8px 5px 5px;border-radius:12px} .lcc .wgb > .wg{margin:2px 5px 8px} .lcc .cr,.lcc .wg + .cr{padding:12px 11px 11px}}
/* ============ end v6 ============ */
